import {buildPack,toSetupConfig,nudgeSetupValue,setupReviewRound} from './setup.js';
import {createSetupMotion} from './setup-motion.js';
import {createSetupEntrance,createSetupDialogMotion} from './setup-entry-motion.js';

// Owns only the temporary wizard; the saved draft changes in onCreate.
export function mountSetup(host,{hasDraft=false,draftName='',entryOrigin=null,entryScene=null,onCreate,onCancel,onBackup}){
 host.innerHTML=`<div id="sm-flow" aria-label="Создание пака SIGameMaker">
 <header class="sf-header"><img src="./assets/logo-horizontal.png" alt="SIGameMaker"></header>
 <nav class="sf-progress" aria-label="Этапы создания"><button type="button" data-step="0" class="cursor-interaction"><span>1</span>О вашей игре</button><i></i><button type="button" data-step="1" class="cursor-interaction"><span>2</span>Структура пака</button><i></i><button type="button" data-step="2" class="cursor-interaction"><span>3</span>Всё готово</button></nav>
 <main class="nu-main"><div class="sf-heading" id="nu-heading"><div><h1 id="nu-title"></h1><p id="nu-subtitle"></p></div></div><div id="nu-stage"></div><div class="nu-footer"><div class="nu-footer-start"><button type="button" class="sf-back nu-menu-anchor cursor-interaction" id="nu-exit">← В меню</button><button type="button" class="sf-back cursor-interaction" id="nu-back">← Назад</button></div><span id="nu-note"></span><button type="button" class="sf-primary cursor-interaction" id="nu-next"></button></div></main>
 <footer id="nu-storage-note">Новый пак создастся только после подтверждения на последнем экране.</footer>
 <div class="nu-toast" role="status" hidden></div>
 <div class="nu-overlay" tabindex="-1" hidden><div class="nu-backdrop" aria-hidden="true"></div><div class="nu-modal" role="dialog" aria-modal="true" aria-labelledby="nu-modal-title"><div class="nu-modal-heading"><h2 id="nu-modal-title"></h2><button type="button" class="nu-close cursor-interaction" data-close-modal aria-label="Закрыть окно">×</button></div><div id="nu-modal-body"></div></div></div>
</div>`;
 let busy=false,transitioning=false,closingModal=false,openingModal=false,modalOpening=Promise.resolve(),ownedDialogMotion=null,toastOwner=null;
 const root=host.querySelector('#sm-flow'),stage=root.querySelector('#nu-stage'),next=root.querySelector('#nu-next'),back=root.querySelector('#nu-back'),overlay=root.querySelector('.nu-overlay'),modal=root.querySelector('.nu-modal'),modalBody=root.querySelector('#nu-modal-body'),toast=root.querySelector('.nu-toast');
 let id=1;const round=(type='standard',index=0,themes=6,q=5)=>({id:id++,type,name:type==='final'?'Финал':type==='interlude'?'Интерлюдия':index===0?'Первый раунд':index===1?'Второй раунд':`Раунд ${index+1}`,themes,questions:type==='final'?1:q,base:100,step:100,multiply:true});
 let s={step:0,furthest:0,name:'',author:'',english:false,chosen:false,rounds:[],selected:null},menuOpen=false,modalKind='',modalOwner=null,undo=null,existing=hasDraft;
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const noun=(n,a,b,c)=>n%100>=11&&n%100<=14?c:n%10===1?a:n%10>=2&&n%10<=4?b:c;
 const themes=n=>`${n} ${noun(n,'тема','темы','тем')}`;const questions=n=>`${n} ${noun(n,'вопрос','вопроса','вопросов')}`;
 const active=()=>s.rounds.find(r=>r.id===s.selected)||s.rounds[0];
 const ordinary=()=>s.rounds.filter(r=>r.type!=='final');
 const price=(r,j)=>r.type==='interlude'?r.base:(r.base+j*r.step)*(r.multiply?ordinary().findIndex(v=>v.id===r.id)+1:1);
 const totals=()=>({themes:s.rounds.reduce((n,r)=>n+r.themes,0),questions:s.rounds.reduce((n,r)=>n+r.themes*r.questions,0)});
 function notify(text,restore=null,owner=next){undo=restore;toastOwner=owner;toast.innerHTML=`<span>${esc(text)}</span>${restore?'<button type="button" class="cursor-interaction" data-undo>Отменить</button>':''}`;toast.hidden=false;motion.toast(toast,owner);}
 function showModal(title,body,{kind='info',small=true,owner=next}={}){modalKind=kind;modalOwner=owner;root.querySelector('#nu-modal-title').textContent=title;modalBody.innerHTML=body;modal.classList.toggle('nu-small-modal',small);modal.classList.toggle('nu-preset-modal',kind==='preset');overlay.hidden=false;openingModal=true;setBackgroundInert(true);overlay.focus({preventScroll:true});ownedDialogMotion=kind==='preset'?presetMotion:['help','replace'].includes(kind)?createSetupDialogMotion(root,modal,overlay,owner):null;const opening=ownedDialogMotion?ownedDialogMotion.open():motion.modal(modal,owner);modalOpening=Promise.resolve(opening).then(()=>{openingModal=false;if(!overlay.hidden&&!closingModal)overlay.querySelector('[data-close-modal]').focus();});}
 async function closeModal(){if(closingModal||transitioning)return;closingModal=true;if(ownedDialogMotion)await ownedDialogMotion.close();else await motion.dismiss(modal);ownedDialogMotion=null;const was=modalKind;overlay.hidden=true;setBackgroundInert(false);modalKind='';if(was==='preset'&&!s.chosen){s.step=0;render();}if(modalOwner?.isConnected)modalOwner.focus();closingModal=false;}
 function validate(){const controls=[...stage.querySelectorAll('input')];let bad=null;for(const input of controls){input.setCustomValidity('');let text='';if((input.dataset.key==='name'||input.dataset.key==='roundName')&&!input.value.trim())text=input.dataset.key==='name'?'Введите название пака.':'Введите название раунда.';else if(!input.validity.valid)text=`Введите целое число от ${input.min} до ${input.max}.`;if(text){input.setCustomValidity(text);input.setAttribute('aria-invalid','true');bad??=input;}else input.removeAttribute('aria-invalid');const error=stage.querySelector(`[data-error="${input.dataset.key}"]`);if(error){error.textContent=text;error.hidden=!text;}}if(bad){bad.focus();bad.reportValidity();return false;}return true;}
 function sync(){root.querySelectorAll('[data-step]').forEach((b,i)=>{b.disabled=i>s.furthest;b.classList.toggle('sf-done',i<s.step);b.querySelector('span').textContent=i<s.step?'✓':i+1;if(i===s.step)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});root.querySelector('#nu-heading').hidden=s.step===2;root.querySelector('#nu-title').textContent=s.step===0?'Начнём с вашей игры':'Соберите игровое поле';root.querySelector('#nu-subtitle').textContent=s.step===0?'Дайте ей имя и выберите язык вопросов.':'Выберите раунд сверху. Настройки слева сразу меняют его поле.';root.querySelector('.nu-footer').classList.toggle('is-ready',s.step===2);back.hidden=s.step===0;back.textContent=s.step===2?'← К настройке структуры':'← О вашей игре';next.textContent=s.step===0?(s.chosen?'К структуре пака →':'Выбрать основу →'):s.step===1?'Проверить основу →':'Создать пак и перейти к вопросам →';root.querySelector('#nu-note').hidden=s.step===0;root.querySelector('#nu-note').textContent=s.step===0?'':'Темы и вопросы заполните в редакторе';root.querySelector('#nu-storage-note').textContent=existing?'Текущий черновик будет заменён только после создания нового пака.':'Новый пак создастся только после подтверждения на последнем экране.';}
 function render(){sync();if(s.step===0)renderAbout();if(s.step===1)renderEditor();if(s.step===2)renderReady();}
 function renderAbout(){stage.innerHTML=`<div class="nu-about-wrap"><section data-motion-surface class="nu-about-card" aria-label="Сведения о вашей игре"><label class="nu-name-label" for="nu-pack-name">Название вашей игры</label><input class="nu-name-input" id="nu-pack-name" data-key="name" value="${esc(s.name)}" placeholder="Например, Киновечер с друзьями" required maxlength="150" aria-describedby="nu-name-error"><span class="nu-error" id="nu-name-error" data-error="name" hidden></span><div class="nu-about-bottom"><label><span class="nu-author-label">Автор <small>Необязательно, можно изменить позже</small></span><input class="nu-author-input" data-key="author" value="${esc(s.author)}" placeholder="Как вас представить?" maxlength="150"></label><div class="nu-language-group"><span class="nu-language-label" id="nu-language-label">Язык вопросов</span><button type="button" class="nu-language cursor-interaction" id="nu-language" aria-pressed="${s.english}" aria-label="Язык вопросов: ${s.english?'английский':'русский'}. Нажмите, чтобы переключить"><span class="nu-language-thumb" aria-hidden="true"></span><span class="nu-ru">Русский</span><span class="nu-en">English</span></button></div></div></section></div>`;}
 function choosePreset(){const miniature=(n,q,final=false)=>`<span class="nu-mini-board ${final?'is-final':''}">${diagramBoard(n,q)}</span>`;showModal('С чего начнём?',`<p>Выберите основу — дальше её можно настроить под свою игру.</p><div class="nu-preset-grid"><button type="button" class="nu-preset cursor-interaction" data-preset="classic" aria-label="Классическая игра: 2 раунда по 6 тем, по 5 вопросов, финал из 7 тем"><span class="nu-preset-art" aria-hidden="true">${miniature(6,5)}${miniature(6,5)}${miniature(7,1,true)}</span><strong>Классическая игра</strong><span class="nu-preset-description"><span>2 раунда + финал</span><span>6 тем по 5 вопросов</span></span></button><button type="button" class="nu-preset cursor-interaction" data-preset="short" aria-label="Короткая игра: 1 раунд, 4 темы по 5 вопросов, без финала"><span class="nu-preset-art" aria-hidden="true">${miniature(4,5)}</span><strong>Короткая игра</strong><span class="nu-preset-description"><span>1 раунд без финала</span><span>4 темы по 5 вопросов</span></span></button><button type="button" class="nu-preset cursor-interaction" data-preset="blank" aria-label="С чистого листа: 1 раунд, 1 тема, 1 вопрос"><span class="nu-preset-art" aria-hidden="true"><span class="nu-mini-blank"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"><path d="M12 5v14M5 12h14"/></svg></span></span><strong>С чистого листа</strong><span class="nu-preset-description"><span>Ваша структура</span><span>Начните с одного вопроса</span></span></button></div>`,{kind:'preset',small:false});}

 async function applyPreset(preset){if(busy||transitioning||closingModal)return;transitioning=true;try{await modalOpening;if(overlay.hidden)return;s.rounds=preset==='classic'?[round(),round('standard',1),round('final',2,7,1)]:preset==='short'?[round('standard',0,4,5)]:[round('standard',0,1,1)];s.selected=s.rounds[0].id;s.chosen=true;s.step=1;s.furthest=Math.max(s.furthest,1);menuOpen=false;clearToast();const source=overlay.querySelector(`[data-preset="${preset}"]`);await motion.fromPreset(source,render,()=>{presetMotion.commit();ownedDialogMotion=null;overlay.hidden=true;setBackgroundInert(false);modalKind='';openingModal=false;});stage.querySelector('#nu-round-name')?.focus({preventScroll:true});}finally{transitioning=false;}}

 function go(step,origin=null,reviewRound=null){if(step===s.step||transitioning)return;if(s.step===2&&step===1)s.selected=setupReviewRound(s.rounds,reviewRound)?.id;menuOpen=false;clearToast();if(step===1&&!s.chosen){choosePreset();return;}if(step===2){const bad=s.rounds.find(r=>!r.name.trim());if(bad){s.selected=bad.id;s.step=1;render();validate();return;}}const previous=s.step;s.step=step;s.furthest=Math.max(s.furthest,step);transitionStage(previous,origin);}
 function boardCard(r){return `<section class="nu-gameboard" data-board-round="${r.id}" aria-label="Игровое поле: ${esc(r.name)}"><div class="nu-board-heading"><h2></h2><span></span></div><div class="nu-board-rows"></div><div class="nu-board-signature"><span>SIGameMaker</span><b>✦</b></div></section>`;}
 function renderEditor(){stage.innerHTML=`<section class="nu-editor"><div class="nu-roundbar"><nav class="nu-round-tabs studio-round-tabs" aria-label="Раунды пака"></nav></div><div class="nu-editor-body"><section class="nu-settings" aria-label="Настройки выбранного раунда"></section><div class="nu-canvas"><div class="nu-board-deck">${s.rounds.map(boardCard).join('')}</div><button type="button" class="nu-help cursor-interaction" data-help>Как это устроено?</button></div></div></section>`;renderSettings();updateBoard();const nav=stage.querySelector('.nu-round-tabs'),tab=nav.querySelector('[aria-current]');if(tab)nav.scrollLeft=Math.max(0,tab.offsetLeft-nav.offsetLeft-nav.clientWidth+tab.offsetWidth+10);}
 function field(key,label,value,min,max){return `<div class="nu-number-field"><label for="nu-value-${key}">${label}</label><div class="nu-number-control"><button type="button" data-nudge="${key}" data-delta="-1" aria-label="Уменьшить: ${label}">−</button><input id="nu-value-${key}" type="number" inputmode="numeric" data-key="${key}" value="${value}" min="${min}" max="${max}" step="1" required><button type="button" data-nudge="${key}" data-delta="1" aria-label="Увеличить: ${label}">+</button></div><span class="nu-error" data-error="${key}" hidden></span></div>`;}
 function renderSettings(){const r=active(),final=r.type==='final',interlude=r.type==='interlude';stage.querySelector('.nu-settings').innerHTML=`<div class="nu-setting-namebar"><input id="nu-round-name" class="nu-round-title" aria-label="Название раунда" placeholder="Название раунда" data-key="roundName" value="${esc(r.name)}" required maxlength="100"><button type="button" class="nu-remove cursor-interaction" data-delete aria-label="Удалить выбранный раунд" ${!final&&ordinary().length===1?'disabled data-tooltip="Нужен хотя бы один обычный раунд"':''}>×</button></div><span class="nu-error" data-error="roundName" hidden></span><section class="nu-setting-group nu-composition" aria-label="Наполнение раунда"><div class="nu-count-equation">${field('themes',final?'Тем в финале':'Тем в раунде',r.themes,1,12)}${final?'<div class="nu-final-count"><span>Вопрос в теме</span><b>1</b></div>':field('questions','Вопросов в теме',r.questions,1,10)}</div><div class="nu-count-total"><span>Всего в раунде</span><strong data-count-total></strong></div></section><section class="nu-setting-group nu-price-design" aria-label="Стоимость вопросов">${final?'<p class="nu-setting-hint">По одному вопросу в каждой теме. Стоимость определяют ставки игроков.</p>':interlude?`${field('base','Стоимость вопросов',r.base,0,9999)}<p class="nu-setting-hint">Одна цена для всех вопросов интерлюдии.</p>`:`<div class="nu-price-inputs">${field('base','Первая цена',r.base,0,9999)}${field('step','Шаг цены',r.step,0,9999)}</div><label class="nu-multiplier"><input type="checkbox" data-key="multiply" ${r.multiply?'checked':''}><span>Умножать на номер раунда<small data-multiplier-hint></small></span></label>`}</section>`;}
 function updateParameterSummary(){const r=active();stage.querySelector('[data-count-total]').textContent=questions(r.themes*r.questions);const hint=stage.querySelector('[data-multiplier-hint]');if(hint)hint.textContent=r.multiply?`Сейчас ×${ordinary().findIndex(v=>v.id===r.id)+1}`:'Одинаковая шкала во всех раундах';for(const button of stage.querySelectorAll('[data-nudge]')){const input=stage.querySelector(`[data-key="${button.dataset.nudge}"]`);button.disabled=Number(button.dataset.delta)<0?Number(input.value)<=Number(input.min):Number(input.value)>=Number(input.max);}}
 function updateBoard(){
  if(s.step!==1)return;const r=active(),nav=stage.querySelector('.nu-round-tabs'),scroll=nav.scrollLeft;
  const tabsHTML=s.rounds.map((v,i)=>`<div class="studio-round-item" data-round-id="${v.id}" ${r.id===v.id?'data-current="true"':''}><button type="button" class="studio-round-handle" aria-label="Переместить раунд ${esc(v.name)}" title="Перетащите, чтобы изменить порядок · Alt + ← / →" aria-keyshortcuts="Alt+ArrowLeft Alt+ArrowRight" ${s.rounds.length<2?'disabled':''}>⠿</button><button type="button" class="studio-round-tab cursor-interaction" data-round="${v.id}" data-motion-round="${v.id}" ${r.id===v.id?'aria-current="true"':''}><span data-round-number>${v.type==='final'?'⚑':v.type==='interlude'?'♪':String(i+1).padStart(2,'0')}</span><span class="studio-round-name">${esc(v.name)||'Название раунда'}</span></button></div>`).join('')+`<button type="button" class="studio-add-round cursor-interaction" aria-label="Добавить раунд" title="Добавить раунд" aria-haspopup="dialog" data-add-menu>+</button>`;
  motion.tabs(nav,tabsHTML);nav.scrollLeft=scroll;
  const selectedIndex=s.rounds.indexOf(r);
  for(const card of stage.querySelectorAll('[data-board-round]')){
   const v=s.rounds.find(v=>v.id===Number(card.dataset.boardRound));if(!v){card.remove();continue;}
   const current=v===r,index=s.rounds.indexOf(v),distance=index-selectedIndex;
   card.classList.toggle('is-active',current);card.classList.toggle('is-distant',Math.abs(distance)>=2);card.classList.toggle('is-final',v.type==='final');card.inert=!current;card.setAttribute('aria-hidden',String(!current));
   if(current){card.setAttribute('data-motion-surface','');card.dataset.motionRound=String(v.id);}else{card.removeAttribute('data-motion-surface');card.removeAttribute('data-motion-round');}
   card.style.setProperty('--nu-card-side',String(Math.max(-3,Math.min(3,distance))));card.style.zIndex=String(current?20:10-Math.min(8,Math.abs(distance)));
   card.querySelector('.nu-board-heading h2').textContent=v.name||'Название раунда';card.querySelector('.nu-board-heading>span').textContent=`${themes(v.themes)} · ${questions(v.questions)} в теме`;
   const rows=card.querySelector('.nu-board-rows'),top=rows.scrollTop,boardHTML=Array.from({length:v.themes},(_,i)=>`<div class="nu-board-row"><span>Тема ${i+1}</span><div class="nu-board-cells" style="--nu-q:${v.questions}">${Array.from({length:v.questions},(_,j)=>`<b>${v.type==='final'?'Ставка':price(v,j)}</b>`).join('')}</div></div>`).join('');
   const digits=Math.max(...Array.from({length:v.questions},(_,i)=>String(price(v,i)).length));card.style.setProperty('--nu-q',String(v.questions));card.style.setProperty('--nu-cell-min',`${Math.max(45,digits*9+12)}px`);
   if(card._boardHTML!==boardHTML){if(current)motion.board(rows,boardHTML);else rows.innerHTML=boardHTML;card._boardHTML=boardHTML;}rows.scrollTop=top;
  }
  updateParameterSummary();
 }
 async function selectRound(id){if(!validate()||id===s.selected)return;const settings=stage.querySelector('.nu-settings');s.selected=id;renderSettings();updateBoard();stage.querySelector('.nu-round-tabs [aria-current]')?.scrollIntoView({block:'nearest',inline:'nearest'});await motion.settingsSlide(settings);}
 function diagramBoard(n,q){return `<span class="nu-diagram-board" style="--nu-themes:${n};--nu-questions:${q}" aria-hidden="true">${Array.from({length:n},()=>`<span class="nu-diagram-theme">${'<i></i>'.repeat(q)}</span>`).join('')}</span>`;}
 function renderReady(){const total=totals();stage.innerHTML=`<section class="nu-celebration"><h1>Ваша игра обрела форму.</h1><h2 class="nu-ready-name" data-tooltip="${esc(s.name)}">${esc(s.name)}</h2><div class="nu-round-diagram" aria-label="Схема структуры пака">${s.rounds.map(r=>`<button type="button" class="nu-diagram-round cursor-interaction ${r.type==='final'?'is-final':''}" data-edit-round="${r.id}" data-motion-round="${r.id}" ${r.id===s.selected?'data-motion-surface':''} aria-label="Изменить ${esc(r.name)}: ${themes(r.themes)}, ${questions(r.themes*r.questions)}"><span class="nu-diagram-name"><span>${esc(r.name)}</span><i>${r.type==='final'?'⚑':'↗'}</i></span>${diagramBoard(r.themes,r.questions)}<span class="nu-diagram-caption"><span>${themes(r.themes)}</span><span>${questions(r.themes*r.questions)}</span></span></button>`).join('')}</div><div class="nu-ready-summary" aria-label="Структура пака"><div><strong>${s.rounds.length}</strong><span>${noun(s.rounds.length,'раунд','раунда','раундов')}</span></div><div><strong>${total.themes}</strong><span>${noun(total.themes,'тема','темы','тем')}</span></div><div><strong>${total.questions}</strong><span>${noun(total.questions,'вопрос','вопроса','вопросов')}</span></div></div>${existing?'<p class="nu-replace-note">Новый пак заменит текущий черновик. Перед созданием сохраните его копию.</p>':''}</section>`;}
 function help(){showModal('Как устроен пак',`<div class="nu-help-sections"><section><h3>Раунды</h3><p>Игра проходит по раундам. Переключайте их сверху; кнопка [+] добавляет обычный раунд, финал или интерлюдию.</p></section><section><h3>Темы и вопросы</h3><p>Каждая строка поля — тема, каждая ячейка — будущий вопрос. Названия тем, тексты, ответы и медиа добавите после создания пака.</p></section><section><h3>Цены</h3><p>Первая цена задаёт начало ряда. Шаг — прибавку за каждый следующий вопрос. Умножение на номер раунда делает цены второго раунда вдвое выше, третьего — втрое.</p></section><section><h3>Финал</h3><p>В каждой теме один вопрос. Игроки исключают темы до последней и делают скрытые ставки. Финал в паке один.</p></section></div><div class="nu-help-actions"><button type="button" class="sf-primary cursor-interaction" data-close-modal>Понятно</button></div>`,{kind:'help',small:true,owner:stage.querySelector('[data-help]')});}
 async function create(){if(busy)return;busy=true;next.disabled=true;try{const c=toSetupConfig(s);motion.dispose();await onCreate(buildPack(c));entrance.dispose();}catch(error){notify(error.message);}finally{busy=false;if(next.isConnected)next.disabled=false;}}
 function advance(){if(busy||transitioning||!validate())return;if(s.step===0){if(!s.chosen)choosePreset();else go(1);}else if(s.step===1){const bad=s.rounds.find(r=>!r.name.trim());if(bad){s.selected=bad.id;renderEditor();validate();return;}go(2);}else if(existing){showModal('Создать новый пак?',`<p>Черновик «${esc(draftName)}» будет заменён. Можно сначала скачать его копию. Замену можно отменить в редакторе.</p><div class="nu-help-actions"><button type="button" data-backup>Скачать текущий .siq</button><button type="button" class="sf-primary" data-create>Создать новый пак</button></div>`,{kind:'replace'});}else create();}
 function addRound(type){undo=null;clearToast();if(type==='final'&&s.rounds.some(r=>r.type==='final'))return;if(type!=='final'&&ordinary().length>=10)return;const r=round(type,ordinary().length,type==='final'?7:6,5),finalIndex=s.rounds.findIndex(v=>v.type==='final');if(type!=='final'&&finalIndex>=0)s.rounds.splice(finalIndex,0,r);else s.rounds.push(r);stage.querySelector('.nu-board-deck').insertAdjacentHTML('beforeend',boardCard(r));updateBoard();stage.querySelector(`[data-board-round="${r.id}"]`).getBoundingClientRect();selectRound(r.id);stage.querySelector('.nu-round-tabs [aria-current]')?.scrollIntoView({block:'nearest',inline:'nearest'});}


 const motion=createSetupMotion(root),entrance=createSetupEntrance(root,entryScene),presetMotion=createSetupDialogMotion(root,modal,overlay,next);
 function clearToast(){if(!toast.hidden)motion.hide(toast,toastOwner||next);}
 function setBackgroundInert(value){for(const el of root.children)if(el!==overlay&&el!==toast)el.inert=value;}
 
 async function transitionStage(previous,origin){if(transitioning)return;transitioning=true;try{await (Math.min(previous,s.step)===0?motion.page(stage,render,s.step-previous):Math.min(previous,s.step)===1&&Math.max(previous,s.step)===2?motion.review(render,s.step-previous):motion.stage(stage,render,s.step-previous,origin));}finally{transitioning=false;}const focus=stage.querySelector(s.step===0?'#nu-pack-name':s.step===1?'#nu-round-name':'.nu-celebration h1');if(focus){if(focus.tagName==='H1')focus.tabIndex=-1;focus.focus({preventScroll:true});}}
 next.addEventListener('click',advance);back.addEventListener('click',()=>{if(!transitioning&&!busy&&validate())go(s.step===2?1:0);});root.querySelector('#nu-exit').addEventListener('click',async()=>{if(busy||transitioning||closingModal)return;transitioning=true;try{motion.dispose();let home;if(s.step!==0){s.step=0;home=await motion.page(stage,render,-1,{duration:220,easing:'linear',overlap:80,continueWith:({offset}={})=>entrance.close({duration:300,incomingOffset:offset})});}else home=await entrance.close();onCancel(home);entrance.dispose();home?.querySelector('[data-action="create-pack"]')?.focus({preventScroll:true});}finally{transitioning=false;}});
 root.querySelectorAll('[data-step]').forEach(b=>b.addEventListener('click',()=>{const target=Number(b.dataset.step);if(transitioning||busy||!validate())return;go(target);}));
 stage.addEventListener('input',event=>{const input=event.target,key=input.dataset.key;if(!key)return;undo=null;clearToast();input.setCustomValidity('');input.removeAttribute('aria-invalid');const error=stage.querySelector(`[data-error="${key}"]`);if(error)error.hidden=true;if(s.step===0){s[key]=input.value;return;}const r=active();if(input.type==='number'){r[key]=input.value===''?NaN:Number(input.value);if(!input.validity.valid)return;}else if(input.type==='checkbox')r[key]=input.checked;else if(key==='roundName')r.name=input.value;updateBoard();});
 stage.addEventListener('click',event=>{
  const b=event.target.closest('button');if(!b||transitioning)return;
  if(b.dataset.nudge){const input=stage.querySelector(`[data-key="${b.dataset.nudge}"]`);input.value=String(nudgeSetupValue(input.value,b.dataset.nudge,Number(b.dataset.delta),Number(input.min),Number(input.max)));input.dispatchEvent(new Event('input',{bubbles:true}));return;}
  if(b.id==='nu-language')motion.language(b,()=>{s.english=!s.english;b.setAttribute('aria-pressed',String(s.english));b.setAttribute('aria-label',`Язык вопросов: ${s.english?'английский':'русский'}. Нажмите, чтобы переключить`);});
  if(b.dataset.round)selectRound(Number(b.dataset.round));
  if(b.hasAttribute('data-add-menu')){if(validate())root.dispatchEvent(new CustomEvent('setup-open-round-picker',{bubbles:true,detail:{owner:b,hasFinal:s.rounds.some(r=>r.type==='final'),atLimit:ordinary().length>=10}}));}
  if(b.hasAttribute('data-help'))help();
  if(b.hasAttribute('data-delete')){const r=active();if(r.type!=='final'&&ordinary().length===1)return;const before=structuredClone(s.rounds),selected=s.selected,index=s.rounds.findIndex(v=>v.id===r.id),owner=motion.anchor(b);motion.update(stage,()=>{s.rounds.splice(index,1);s.selected=s.rounds[Math.min(index,s.rounds.length-1)].id;renderEditor();},b);notify(`Раунд «${r.name}» удалён.`,{rounds:before,selected},owner);}
  if(b.dataset.editRound){s.selected=Number(b.dataset.editRound);stage.querySelector('[data-motion-surface]')?.removeAttribute('data-motion-surface');b.setAttribute('data-motion-surface','');go(1,null,Number(b.dataset.editRound));}
 });
 let outsidePress=false;
 overlay.addEventListener('pointerdown',event=>{outsidePress=event.button===0&&event.target===overlay;});
 overlay.addEventListener('pointerup',event=>{outsidePress=outsidePress&&event.target===overlay;});
 overlay.addEventListener('pointercancel',()=>{outsidePress=false;});
 overlay.addEventListener('click',async event=>{const outside=outsidePress&&event.target===overlay;outsidePress=false;if(busy||closingModal||transitioning)return;if(['preset','replace'].includes(modalKind)&&outside){closeModal();return;}const b=event.target.closest('button');if(!b)return;if(b.dataset.preset)applyPreset(b.dataset.preset);else if(b.hasAttribute('data-close-modal'))closeModal();else if(b.hasAttribute('data-create')){await closeModal();await create();}else if(b.hasAttribute('data-backup')){busy=true;b.disabled=true;try{await onBackup();b.textContent='Копия скачана';}catch(error){notify(error.message);}finally{busy=false;b.disabled=false;}}});
 toast.addEventListener('click',event=>{if(event.target.closest('[data-undo]')&&undo){const restore=undo;undo=null;motion.update(stage,()=>{s.rounds=restore.rounds;s.selected=restore.selected;clearToast();renderEditor();},event.target.closest('[data-undo]'));}});
 root.addEventListener('click',event=>{if(menuOpen&&!event.target.closest('.nu-roundbar')){menuOpen=false;const menu=stage.querySelector('.nu-add-menu');if(menu)motion.menu(menu,stage.querySelector('[data-add-menu]'),false);stage.querySelector('[data-add-menu]')?.setAttribute('aria-expanded','false');}});
 root.addEventListener('keydown',event=>{if(!overlay.hidden){event.stopPropagation();if(event.key==='Escape'){event.preventDefault();event.stopPropagation();closeModal();}if(event.key==='Tab'&&openingModal){event.preventDefault();overlay.focus({preventScroll:true});return;}if(event.key==='Tab'){const controls=[...overlay.querySelectorAll('button')].filter(b=>!b.disabled),first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}}return;}if(event.key==='Escape'&&menuOpen){menuOpen=false;motion.menu(stage.querySelector('.nu-add-menu'),stage.querySelector('[data-add-menu]'),false);stage.querySelector('[data-add-menu]').setAttribute('aria-expanded','false');}if(event.key==='Enter'&&event.target.matches('input')){event.preventDefault();advance();}});
 root.addEventListener('setup-add-round',event=>{if(busy||transitioning||!validate())return;const type=event.detail.type;if(!['standard','final','interlude'].includes(type))return;if(type==='final'&&s.rounds.some(r=>r.type==='final')||type!=='final'&&ordinary().length>=10)return;event.detail.accepted=true;addRound(type,stage.querySelector('[data-add-menu]'));});
 root.addEventListener('setup-round-move',event=>{if(transitioning||busy||s.step!==1||!validate())return;const {id,beforeId}=event.detail,from=s.rounds.findIndex(r=>String(r.id)===id);if(from<0)return;const next=s.rounds.slice(),[moved]=next.splice(from,1),at=beforeId===null?next.length:next.findIndex(r=>String(r.id)===beforeId);if(at<0)return;next.splice(at,0,moved);if(next.some((r,i)=>r.type==='final'&&i!==next.length-1))return;s.rounds=next;event.detail.accepted=true;queueMicrotask(()=>{if(root.isConnected&&s.step===1){const focused=document.activeElement?.closest('.studio-round-item')?.dataset.roundId;updateBoard();if(focused)stage.querySelector(`.studio-round-item[data-round-id="${focused}"] .studio-round-handle`)?.focus({preventScroll:true});}});});
 render();transitioning=true;Promise.resolve(entryScene?entrance.open():motion.enter(stage,entryOrigin)).finally(()=>{transitioning=false;if(root.isConnected)stage.querySelector('#nu-pack-name')?.focus({preventScroll:true});});

}
